#!/usr/bin/env python3
"""Fast batch prober: feed a dict of name->markdown-body, get name->rendered html."""
import os, shutil, subprocess, sys, tempfile, json

BIN = "/tmp/orig/marmite_ref"

def render_bodies(bodies, binary=BIN, config=None, extra=None, keep=False):
    """bodies: dict name -> markdown body (no front matter). Returns dict name -> html."""
    work = tempfile.mkdtemp(prefix="probe-")
    tdir = os.path.join(work, "templates")
    os.makedirs(tdir)
    open(os.path.join(tdir, "content.html"), "w").write("{{ content.html }}")
    open(os.path.join(tdir, "list.html"), "w").write("")
    open(os.path.join(tdir, "group.html"), "w").write("")
    for name, body in bodies.items():
        with open(os.path.join(work, name + ".md"), "w") as f:
            f.write("---\ntitle: T\nslug: %s\n---\n" % name)
            f.write(body)
    if config:
        open(os.path.join(work, "marmite.yaml"), "w").write(config)
    for rel, content in (extra or {}).items():
        p = os.path.join(work, rel)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, "w").write(content)
    site = os.path.join(work, "_site")
    p = subprocess.run([binary, work, site], capture_output=True, text=True)
    out = {}
    if os.path.isdir(site):
        for name in bodies:
            f = os.path.join(site, name + ".html")
            if os.path.exists(f):
                out[name] = open(f).read()
    if keep:
        print("workdir:", work, "site:", site, file=sys.stderr)
    else:
        shutil.rmtree(work, ignore_errors=True)
    return out, p

def show(bodies, **kw):
    out, p = render_bodies(bodies, **kw)
    for name in bodies:
        print("=" * 20, name)
        print("IN:  " + repr(bodies[name]))
        print("OUT: " + (repr(out[name]) if name in out else "<MISSING>"))
    if p.returncode != 0:
        print("RC", p.returncode, p.stdout[-3000:], p.stderr[-3000:])

if __name__ == "__main__":
    data = json.load(sys.stdin)
    show(data)

